import React from "react";
import { Link } from "react-router-dom";
import "./Navbar.css"; // If you have a separate CSS file for styling

const Navbar = () => {
  return (
    <nav className="navbar">
      <ul>
        <li>
          <Link to="/">Chat</Link>
        </li>
        <li>
          <Link to="/youtube">YouTube</Link> {/* New Link */}
        </li>
      </ul>
    </nav>
  );
};

export default Navbar;
